def transform(grid):
    h, w = len(grid), len(grid[0])

    # Find rows with non-zero values
    active_rows = []
    for i, row in enumerate(grid):
        if any(v != 0 for v in row):
            active_rows.append(i)

    if not active_rows:
        return [[0]*w for _ in range(h)]

    for row_idx in active_rows:
        source = grid[row_idx]

        # Check each column for special values
        for col in range(w):
            val = source[col]
            if val == 0:
                continue

            left = source[col-1] if col > 0 else None
            right = source[col+1] if col < w-1 else None

            # Column is special if value differs from neighbors
            is_special = False
            if left is not None and right is not None:
                if left != val and right != val:
                    is_special = True
            elif left is not None and left != val:
                is_special = True
            elif right is not None and right != val:
                is_special = True

            if is_special:
                # Project upward
                num_units = val

                for dist in range(1, num_units + 1):
                    if row_idx - dist < 0:
                        break
                    target_row = row_idx - dist

                    # First unit gets the source value
                    if dist == 1:
                        grid[target_row][col] = val
                    else:
                        grid[target_row][col] = 1
                    break

                # If we have more room, fill remaining with 1s
                remaining = num_units - 1
                for r in range(target_row - 1, max(-1, row_idx - num_units - 1), -1):
                    if r >= 0 and r < h:
                        grid[r][col] = 1

    return grid

